using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpHttpServer;

public class ConfigResource : ResourceSource
{
    public override ResourceTemplateInfo? TemplateInfo => null;

    public override ResourceInfo Info => new()
    {
        Uri = "config://app/settings",
        Name = "Application Settings",
        Description = "Returns the current application configuration",
        MimeType = "application/json",
    };

    public override ValueTask<ReadResourceResult> ReadAsync(
        RequestContext<ReadResourceRequestParams> request,
        CancellationToken cancellationToken = default)
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Features = new { EnableLogging = true, MaxRetries = 3 },
        };

        return ValueTask.FromResult(new ReadResourceResult
        {
            Contents =
            [
                new TextResourceContents
                {
                    Uri = Info.Uri,
                    MimeType = "application/json",
                    Text = JsonSerializer.Serialize(config, new JsonSerializerOptions
                    {
                        WriteIndented = true,
                    }),
                },
            ],
        });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTool
{
    [McpServerTool, Description("Greets a user by name")]
    public static string Greet([Description("The name to greet")] string name)
        => $"Hello, {name}! Welcome to the MCP HTTP server.";
}

