using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerResourceType]
public class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "Application Settings", MimeType = "application/json")]
    [Description("Returns the current application configuration")]
    public static string GetSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Features = new { EnableLogging = true, MaxRetries = 3 },
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/feature/{name}", Name = "Feature Flag")]
    [Description("Returns the status of a specific feature flag")]
    public static TextResourceContents GetFeatureFlag(RequestContext<ReadResourceRequestParams> context, string name)
    {
        var flags = new Dictionary<string, bool>
        {
            ["logging"] = true,
            ["caching"] = false,
            ["darkMode"] = true,
        };

        var enabled = flags.TryGetValue(name, out var value) && value;

        return new TextResourceContents
        {
            Uri = context.Params!.Uri!,
            MimeType = "application/json",
            Text = JsonSerializer.Serialize(new { Feature = name, Enabled = enabled }),
        };
    }
}

