1. using System.ComponentModel;
2. using System.Text.Json;
3. using ModelContextProtocol.Protocol;
4. using ModelContextProtocol.Server;
5. 
6. namespace McpHttpServer;
7. 
8. [McpServerResourceType]
9. public class ConfigResource
10. {
11.     [McpServerResource(UriTemplate = "config://app/settings", Name = "Application Settings", MimeType = "application/json")]
12.     [Description("Returns the current application configuration")]
13.     public static string GetSettings()
14.     {
15.         var config = new
16.         {
17.             AppName = "McpHttpServer",
18.             Version = "1.0.0",
19.             Features = new { EnableLogging = true, MaxRetries = 3 },
20.         };
21. 
22.         return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
23.     }
24. 
25.     [McpServerResource(UriTemplate = "config://app/feature/{name}", Name = "Feature Flag")]
26.     [Description("Returns the status of a specific feature flag")]
27.     public static TextResourceContents GetFeatureFlag(RequestContext<ReadResourceRequestParams> context, string name)
28.     {
29.         var flags = new Dictionary<string, bool>
30.         {
31.             ["logging"] = true,
32.             ["caching"] = false,
33.             ["darkMode"] = true,
34.         };
35. 
36.         var enabled = flags.TryGetValue(name, out var value) && value;
37. 
38.         return new TextResourceContents
39.         {
40.             Uri = context.Params!.Uri!,
41.             MimeType = "application/json",
42.             Text = JsonSerializer.Serialize(new { Feature = name, Enabled = enabled }),
43.         };
44.     }
45. }
46.

